r"""venues.py — USR-01 (2026-11-11): the venue roster. Every exchange on the record keyed to its node, with what the market file already carries:
the regulator, the halts page and the disclosure channel. Nothing new is read.
  the record         each node's door/facts.json (records_by_exchange) from the newest research drop: the exchange codes the record holds, with their issuer counts
  the market file    C:\ALLOOLOO\BOOK\<cc>\sections\<cc>.eco.v<N>.json (newest N): exchanges_and_venues, competent_authorities, halts_sources, information_stores
                     — each with its source page and read date; a field the market file holds as not_found is not_on_record here
Writes CM-KG\RESEARCH\venues.json (the roster of record) and CM-KG\ESTATE\worker\venues-data.js (the estate's copy: each node page's Coverage line and the
venues block of its facts.json). Deterministic: no clock value. Usage: python -X utf8 venues.py"""
import os, re, json, glob
BOOK = r'C:\ALLOOLOO\BOOK'; POND = r'C:\ALLOOLOO\CM-KG\POND'; OUT = r'C:\ALLOOLOO\CM-KG\RESEARCH'; JS = r'C:\ALLOOLOO\CM-KG\ESTATE\worker\venues-data.js'
nodes = json.load(open(r'C:\ALLOOLOO\SITE\USR-01\list_nodes.json', encoding='utf-8'))['result']['structuredContent']['nodes']
def newest(cc):
    fs = glob.glob(os.path.join(BOOK, cc, 'sections', f'{cc}.eco.v*.json')); return max(fs, key=lambda f: int(re.search(r'\.v(\d+)\.json$', f).group(1))) if fs else None
def drop(cc):
    b = os.path.join(POND, f'{cc}-cm-kg', 'research'); ds = [d for d in os.listdir(b) if os.path.exists(os.path.join(b, d, 'node.json'))]; return os.path.join(b, sorted(ds, key=lambda d: (d[:10], int(d[11:] or 1)))[-1])
def fld(sec, name):
    f = next((x for x in sec.get('fields', []) if x.get('name') == name), None)
    if not f or f.get('value') in (None, '', 'not_found'): return {'state': 'not_on_record', 'pages_checked': (f or {}).get('pages_checked') or []}
    return {'value': f['value'], 'source': f.get('source_url'), 'read_date': str(f.get('read_at') or '')[:10] or None}
txt = lambda v: v if isinstance(v, str) else '; '.join((x.get('name') or json.dumps(x, ensure_ascii=False)) if isinstance(x, dict) else str(x) for x in v) if isinstance(v, list) else json.dumps(v, ensure_ascii=False)
roster = []; by_node = {}
for n in nodes:
    cc = n['node'].split('-')[0]; f = newest(cc); sec = json.load(open(f, encoding='utf-8')) if f else {'fields': []}
    facts = (json.load(open(os.path.join(drop(cc), 'node.json'), encoding='utf-8')).get('facts') or {}).get('nodes', {}).get(n['node'], {})
    rbx = facts.get('records_by_exchange') or {}; ex = fld(sec, 'exchanges_and_venues'); reg = fld(sec, 'competent_authorities'); halts = fld(sec, 'halts_sources'); chan = fld(sec, 'information_stores')
    named = [x.get('name') if isinstance(x, dict) else str(x) for x in ex['value']] if isinstance(ex.get('value'), list) else [ex['value']] if ex.get('value') else []
    b = by_node[cc] = {'node': n['node'], 'country': n['country'], 'market_file': os.path.basename(f) if f else None, 'exchanges_on_record': rbx, 'exchanges_named': named, 'exchanges_source': ex.get('source'), 'exchanges_read_date': ex.get('read_date'),
                       'coverage': '; '.join(named) if named else None, 'regulator': {**reg, **({'value': txt(reg['value'])} if 'value' in reg else {})}, 'halts_page': {**halts, **({'value': txt(halts['value'])} if 'value' in halts else {})}, 'disclosure_channel': {**chan, **({'value': txt(chan['value'])} if 'value' in chan else {})}}
    for code in sorted(rbx): roster.append({'exchange': code, 'node': n['node'], 'market': cc.upper(), 'country': n['country'], 'issuers_on_record': rbx[code], 'regulator': b['regulator'], 'halts_page': b['halts_page'], 'disclosure_channel': b['disclosure_channel'], 'door': n.get('regional_door') or n.get('door')})
out = {'schema': 'venue-roster v0.1 (USR-01, 2026-11-11)', 'venues': len(roster), 'nodes': len(by_node), 'roster': roster, 'by_node': by_node,
       'note': 'every exchange code on the record, keyed to its node; regulator, halts page and disclosure channel as the market file (the Book, ECO section) carries them, each with source page and read date'}
os.makedirs(OUT, exist_ok=True); json.dump(out, open(os.path.join(OUT, 'venues.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1, sort_keys=True)
open(JS, 'w', encoding='utf-8').write('// venues-data.js — generated by CM-KG\\RAILS\\research\\venues.py (USR-01). Do not edit; regenerate. The venue roster: every exchange on the record keyed to\n// its node, with the regulator, halts page and disclosure channel the market file (the Book, ECO section) carries.\nexport const VENUES = ' + json.dumps({'venues': len(roster), 'by_node': by_node}, ensure_ascii=False, sort_keys=True) + ';\n')
print('venues', len(roster), 'nodes', len(by_node), 'nodes with named exchanges', sum(1 for b in by_node.values() if b['coverage']), 'no regulator', [c for c, b in by_node.items() if 'value' not in b['regulator']], 'no halts page', [c for c, b in by_node.items() if 'value' not in b['halts_page']], 'no channel', [c for c, b in by_node.items() if 'value' not in b['disclosure_channel']])
print(json.dumps(by_node['tw'], ensure_ascii=False)[:900])
